CREATE POLICY "Own pictures read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'pictures' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own pictures insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'pictures' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Own pictures delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'pictures' AND (storage.foldername(name))[1] = auth.uid()::text);